public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BStringsWithTheSameLength solver = new BStringsWithTheSameLength();
        solver.solve(1, in, out);
        out.close();
    }

    static class BStringsWithTheSameLength {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            char[] s = in.next().toCharArray();
            char[] t = in.next().toCharArray();

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.append(s[i]).append(t[i]);
            }
            out.println(sb);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Main {
  static final String ascii = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  public static void main(String args[]){
    Scanner sc = new Scanner(System.in);
    int index = sc.nextInt();
    String str = sc.next();

    if (index == 0){
      System.out.println(str);  
    }else {

      String replaced = "";
      for (int i = 0 ; i < str.length() ; i++){
        char c = str.charAt(i);
        int si = ascii.indexOf(String.valueOf(c));
        int ri = si + index;
        if(ri >= ascii.length()){
          ri = ri - ascii.length();
        }
        replaced = replaced + String.valueOf(ascii.charAt(ri));
      }
      System.out.println(replaced);
    }
  }
}

