		PrintWriter pw = new PrintWriter(System.out);
		int N = sc.nextInt();
		int aCheck = -1, ans = 0;
		ArrayList<Integer> list = new ArrayList<>();
		for(int i = 0; i < N; i++) {
			int a = sc.nextInt();
			if(a == aCheck+1) {
				list.add(aCheck);
			}
			aCheck = a;
		}
		for(int i = 0; i < N; i++) {
			ans += sc.nextInt();
		}

