        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int Q = sc.nextInt();

        String S = sc.next();

        int[] dp = new int[N];
        dp[0] = 0;
        for(int i = 1; i < N; i++){
            if( S.charAt(i-1) == 'A' && S.charAt(i) == 'C' ){
                dp[i]++;
            }
            if(i != N-1) dp[i+1] = dp[i];
        }

        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < Q; i++){
            int l = sc.nextInt() - 1;
            int r = sc.nextInt() - 1;
            sb.append(dp[r] - dp[l]).append("\r\n");
        }

        System.out.println(sb.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] a = new int[n];
      for (int i = 0; i < n; i++)
        a[i] = nextInt();
      return a;
    }

    public long[] nextLongArray(int n) {
      long[] a = new long[n];
      for (int i = 0; i < n; i++)
        a[i] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int n = sc.nextInt();
    int q = sc.nextInt();
    String s = sc.next();
    int[][] questions = new int[q][2];
    for (int i = 0; i < q; i++) questions[i] = sc.nextIntArray(2);
    int[] acs = new int[n + 1];
    acs[0] = 0;
    acs[1] = 0;
    for (int i = 2; i <= n; i++) {
      if(s.substring(i - 2, i).equals("AC")) acs[i] = acs[i - 1] + 1;
      else acs[i] = acs[i - 1];
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < q; i++) {
      if (i > 0) sb.append("\n");
      sb.append(acs[questions[i][1]] - acs[questions[i][0]]);
    }
    System.out.println(sb.toString());
  }
}

