			int val = 1;
			while(val <= k && nn-val >= 1){
				dp[nn] = Math.min(dp[nn], Math.abs(h[nn]-h[nn-val]) + dp[nn-val]);
				val++;
			//System.out.println(Arrays.toString(dp) + " " + val);
			}
			//System.out.println(Arrays.toString(dp));
		}
		System.out.println(dp[n]);
	}

