        int H[] = new int[N];
        for(int i=0; i<N; i++) {
            H[i] = sc.nextInt();
        }

        int X[] = new int[N];
        for(int i=0; i<N; i++) {
            X[i] = Math.abs((T - H[i] * 6) - A);
        }

        int res = 0;
        int minval = X[0];
        for(int i=0; i<N; i++) {
            if(minval > X[i]) {
                minval = X[i];
                res = i;
            }
        }
        System.out.println(String.format("%d", res + 1));
    }
}

